INSERT INTO RULE (
RULEID
, RULE_NM
, RULEALIAS_NM
, RULE_DESC
, RULERETURN_TYPE
, RULESORT_CD
, RULEUSAGE_CD
, ALLRETURN_YN
, USE_YN
, RULE_VERNO
, ACTIVATE_YN
, ACTIVATE_DATETIME
, RULE_STATE
, DEPLOY_DATETIME
, DEPLOY_USERID
, IFID
, FIRSTREG_USERID
, FIRSTREG_DATETIME
, UPDATE_USERID
, UPDATE_DATETIME
, RULE_APPLY_YN
) VALUES (
#{ruleid}
, #{ruleNm}
, #{rulealiasNm}
, #{ruleDesc}
, #{rulereturnType}
, #{rulesortCd}
, #{ruleusageCd}
, #{allreturnYn}
, #{useYn}
, #{ruleVerno}
, #{activateYn}
, NULL
, #{ruleState}
, NULL
, NULL
, #{ifid}
, #{firstregUserid}
, TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
, #{firstregUserid}
, TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
, #{ruleApplyYn}
)

