INSERT INTO RULE_PROGRESS_HISTORY (
RULEID
, RULE_VERNO
, RULE_STATE
, CURRENT_RULE_APPLY_YN
, DEPLOY_WAIT_STATE_APPLY_YN
, UPDATE_USERID
, UPDATE_DATETIME
, HISTORY_NO
) VALUES (
#{ruleid}
, #{ruleVerno}
, #{ruleState}
, (SELECT RULE_APPLY_YN
FROM RULE
WHERE RULEID = #{ruleid})
, #{deployWaitStateApplyYn}
, #{updateUserid}
, TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
, (
SELECT COALESCE(MAX(HISTORY_NO) + 1, 0)
FROM RULE_PROGRESS_HISTORY
WHERE RULEID = #{ruleid}
)
)

