mapper.select:
SELECT RULE_STATE
FROM RULE
WHERE RULEID = #{value}

SELECT DISTINCT '반환항목' AS USE_GUBUN , A.RETURN_ITEMID AS ITEMID , B.ITEM_NM FROM RULERETURNITEM A INNER JOIN RULEITEM B ON A.RETURN_ITEMID = B.ITEMID WHERE RULEID = #{value}
UNION ALL
SELECT DISTINCT '조건식' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) AS ITEMID , B.ITEM_NM FROM RULECONDITION_POSTFIXOBJECT A INNER JOIN RULEITEM B ON SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) = B.ITEMID WHERE A.DATATYPE_CD = '3' AND RULEID = #{value}
UNION ALL
SELECT DISTINCT '반환값' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) AS ITEMID , B.ITEM_NM FROM RULECONDITIONRETURN_POSTOBJECT A INNER JOIN RULEITEM B ON SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) = B.ITEMID WHERE A.DATATYPE_CD = '3' AND RULEID = #{value}

SELECT DISTINCT '조건식' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) AS RULEID , B.RULE_NM , ( SELECT CODE_NM FROM CLOVER_CODE WHERE CODE_TYPE = '604' AND CODE = B.RULE_STATE ) AS RULE_STATE , ( SELECT USER_NM FROM CLOVER_USER WHERE USER_ID = B.UPDATE_USERID ) AS UPDATE_USERID , ( SUBSTR(B.UPDATE_DATETIME, 1, 4) || '/' || SUBSTR(B.UPDATE_DATETIME, 5, 2) || '/' || SUBSTR(B.UPDATE_DATETIME, 7, 2) || ' ' || SUBSTR(B.UPDATE_DATETIME, 9, 2) || ':' || SUBSTR(B.UPDATE_DATETIME, 11, 2) || ':' || SUBSTR(B.UPDATE_DATETIME, 13, 2) ) AS UPDATE_DATETIME , B.RULE_APPLY_YN FROM RULECONDITION_POSTFIXOBJECT A INNER JOIN RULE B ON SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) = B.RULEID WHERE A.DATATYPE_CD = '4' AND A.RULEID = #{value}
UNION ALL
SELECT DISTINCT '반환값' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) AS RULEID , B.RULE_NM , ( SELECT CODE_NM FROM CLOVER_CODE WHERE CODE_TYPE = '604' AND CODE = B.RULE_STATE ) AS RULE_STATE , ( SELECT USER_NM FROM CLOVER_USER WHERE USER_ID = B.UPDATE_USERID ) AS UPDATE_USERID , ( SUBSTR(B.UPDATE_DATETIME, 1, 4) || '/' || SUBSTR(B.UPDATE_DATETIME, 5, 2) || '/' || SUBSTR(B.UPDATE_DATETIME, 7, 2) || ' ' || SUBSTR(B.UPDATE_DATETIME, 9, 2) || ':' || SUBSTR(B.UPDATE_DATETIME, 11, 2) || ':' || SUBSTR(B.UPDATE_DATETIME, 13, 2) ) AS UPDATE_DATETIME , B.RULE_APPLY_YN FROM RULECONDITIONRETURN_POSTOBJECT A INNER JOIN RULE B ON SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) = B.RULEID WHERE A.DATATYPE_CD = '4' AND A.RULEID = #{value}

SELECT DISTINCT '반환항목' AS USE_GUBUN , A.RETURN_ITEMID AS ITEMID , B.ITEM_NM FROM RULERETURNITEM_HIST A INNER JOIN RULEITEM B ON A.RETURN_ITEMID = B.ITEMID WHERE RULEID = #{ruleid} AND RULE_VERNO = #{ruleVerno}
UNION ALL
SELECT DISTINCT '조건식' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) AS ITEMID , B.ITEM_NM FROM RULECONDITION_POSTFIXOBJECT_HI A INNER JOIN RULEITEM B ON SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) = B.ITEMID WHERE A.DATATYPE_CD = '3' AND RULEID = #{ruleid} AND RULE_VERNO = #{ruleVerno}
UNION ALL
SELECT DISTINCT '반환값' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) AS ITEMID , B.ITEM_NM FROM RULECONDITIONRETURN_POSTOB_HI A INNER JOIN RULEITEM B ON SUBSTR(A.OBJECT_DATA, 2, LENGTH(A.OBJECT_DATA) - 2) = B.ITEMID WHERE A.DATATYPE_CD = '3' AND RULEID = #{ruleid} AND RULE_VERNO = #{ruleVerno}

SELECT DISTINCT '조건식' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) AS RULEID , B.RULE_NM , ( SELECT CODE_NM FROM CLOVER_CODE WHERE CODE_TYPE = '604' AND CODE = B.RULE_STATE ) AS RULE_STATE , ( SELECT USER_NM FROM CLOVER_USER WHERE USER_ID = B.UPDATE_USERID ) AS UPDATE_USERID , ( SUBSTR(B.UPDATE_DATETIME, 1, 4) || '/' || SUBSTR(B.UPDATE_DATETIME, 5, 2) || '/' || SUBSTR(B.UPDATE_DATETIME, 7, 2) || ' ' || SUBSTR(B.UPDATE_DATETIME, 9, 2) || ':' || SUBSTR(B.UPDATE_DATETIME, 11, 2) || ':' || SUBSTR(B.UPDATE_DATETIME, 13, 2) ) AS UPDATE_DATETIME , B.RULE_APPLY_YN FROM RULECONDITION_POSTFIXOBJECT_HI A INNER JOIN RULE B ON SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) = B.RULEID WHERE A.DATATYPE_CD = '4' AND A.RULEID = #{ruleid} AND A.RULE_VERNO = #{ruleVerno}
UNION ALL
SELECT DISTINCT '반환값' AS USE_GUBUN , SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) AS RULEID , B.RULE_NM , ( SELECT CODE_NM FROM CLOVER_CODE WHERE CODE_TYPE = '604' AND CODE = B.RULE_STATE ) AS RULE_STATE , ( SELECT USER_NM FROM CLOVER_USER WHERE USER_ID = B.UPDATE_USERID ) AS UPDATE_USERID , ( SUBSTR(B.UPDATE_DATETIME, 1, 4) || '/' || SUBSTR(B.UPDATE_DATETIME, 5, 2) || '/' || SUBSTR(B.UPDATE_DATETIME, 7, 2) || ' ' || SUBSTR(B.UPDATE_DATETIME, 9, 2) || ':' || SUBSTR(B.UPDATE_DATETIME, 11, 2) || ':' || SUBSTR(B.UPDATE_DATETIME, 13, 2) ) AS UPDATE_DATETIME , B.RULE_APPLY_YN FROM RULECONDITIONRETURN_POSTOB_HI A INNER JOIN RULE B ON SUBSTR(A.OBJECT_DATA, 3, LENGTH(A.OBJECT_DATA) - 3) = B.RULEID WHERE A.DATATYPE_CD = '4' AND A.RULEID = #{ruleid} AND A.RULE_VERNO = #{ruleVerno}

SELECT COUNT(*)
FROM RULE
WHERE RULE_STATE != 'D'
AND RULE_NM = #{ruleNm}

    AND RULEID != #{ruleid}

